import torch
import struct

def dequantize_q4_0_block(block_bytes):
    d = struct.unpack('<e', block_bytes[:2])[0]
    qs = block_bytes[2:18]
    values = []
    for i in range(16):
        q_low = (qs[i] & 0x0F) - 8
        q_high = (qs[i] >> 4) - 8
        values.append(q_low * d)
        values.append(q_high * d)
    return torch.tensor(values, dtype=torch.float32)

@torch.no_grad()
def run(activation, weight):
    # Convert bfloat16 to float32 for reference computation
    if hasattr(torch, 'bfloat16') and activation.dtype == torch.bfloat16:
        act_f32 = activation.float()
    else:
        act_f32 = activation

    M, K = act_f32.shape
    N = weight.shape[0]
    num_blocks = K // 32

    weight_dequant = torch.zeros(N, K, dtype=torch.float32)
    for n in range(N):
        for b in range(num_blocks):
            block_values = dequantize_q4_0_block(weight[n, b])
            weight_dequant[n, b*32:(b+1)*32] = block_values

    output = torch.matmul(act_f32, weight_dequant.T)
    # Convert back to bfloat16
    return output.to(torch.bfloat16) if hasattr(torch, 'bfloat16') else output
